// Get buyers and properties from previous nodes
const buyers = $('Query Active Buyers').all()[0]?.json?.data || [];
const properties = $('Query Available Properties').all()[0]?.json?.data || [];

if (buyers.length === 0 || properties.length === 0) {
  return [{ json: { message: 'No buyers or properties to match', buyers_count: buyers.length, properties_count: properties.length } }];
}

// Create match pairs for each buyer-property combination
// We'll process in batches to avoid overwhelming Groq
const matchPairs = [];

for (const buyer of buyers) {
  for (const property of properties) {
    matchPairs.push({
      buyer_id: buyer.id,
      buyer_name: `${buyer.first_name} ${buyer.last_name}`,
      buyer_email: buyer.email,
      buyer_phone: buyer.phone,
      budget_min: buyer.budget_min,
      budget_max: buyer.budget_max,
      preferred_locations: buyer.preferred_locations || [],
      buyer_property_type: buyer.property_type,
      min_bedrooms: buyer.min_bedrooms,
      features_wanted: buyer.features_wanted || [],
      property_id: property.id,
      property_address: property.address,
      property_price: property.price,
      property_type: property.property_type,
      property_bedrooms: property.bedrooms,
      property_bathrooms: property.bathrooms,
      property_features: property.features || [],
      property_description: property.description || ''
    });
  }
}

// Return match pairs for processing
return matchPairs.map(pair => ({ json: pair }));

