// Parse Groq AI response and merge with buyer/property data
const groqResponse = $json;
const content = groqResponse.choices?.[0]?.message?.content || '{}';

let matchResult;
try {
  // Try to extract JSON from the response
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  matchResult = JSON.parse(jsonMatch ? jsonMatch[0] : content);
} catch (e) {
  // Fallback if parsing fails
  matchResult = {
    match_score: 50,
    match_grade: 'fair',
    reasoning: 'Unable to parse AI response',
    key_matches: [],
    concerns: ['Parsing error'],
    suggested_message: 'We found a property that might interest you. Please contact us for details.'
  };
}

const batchData = $('Batch Process Matches').item.json;

return {
  json: {
    buyer_id: batchData.buyer_id,
    buyer_name: batchData.buyer_name,
    buyer_email: batchData.buyer_email,
    buyer_phone: batchData.buyer_phone,
    property_id: batchData.property_id,
    property_address: batchData.property_address,
    property_price: batchData.property_price,
    match_score: matchResult.match_score || 0,
    match_grade: matchResult.match_grade || 'unknown',
    reasoning: matchResult.reasoning || '',
    key_matches: matchResult.key_matches || [],
    concerns: matchResult.concerns || [],
    suggested_message: matchResult.suggested_message || 'Check out this property that matches your criteria!'
  }
};

